// ?onEnter@AIGuardOuterState@@UAE?AW4StateReturnType@@XZ
// partial score=0.55 date=2026-09-08
// cl: /DNDEBUG /MD /EHsc

typedef int Int;
typedef unsigned int UnsignedInt;
typedef float Real;
typedef bool Bool;

enum StateReturnType
{
	STATE_CONTINUE = 0,
	STATE_SUCCESS = -1,
	STATE_FAILURE = -2
};

struct Coord3D
{
	Real x, y, z;
};

class Object;
class Team;
class PolygonTrigger;
class StateMachine;
class BfmeX1011;
class BfmeTeamXQ;

class BfmeX1011
{
public:
	char m_pad[0x38];
	Coord3D m_coord;
};

class BfmeLook1011
{
public:
	BfmeX1011 *bfmeFind1011(Int id);
	char m_pad[0x38];
	UnsignedInt m_frame;
};

class TeamFactory
{
public:
	BfmeTeamXQ *bfmeFindXQ(void *id);
};

class BfmeTeamXQ
{
public:
	void bfmeEstimateXQ(Coord3D *out) const;
};

class Object
{
public:
	Int getLayer() const;
};

class PolygonTrigger
{
public:
	void getCenterPoint(Coord3D *out) const;
};

class AIData
{
public:
	char m_pad[0x3c];
	UnsignedInt m_guardChaseUnitFrames;
};

class AI
{
public:
	char m_pad[0x14];
	AIData *m_aiData;
	static Real getAdjustedVisionRangeForObject(const Object *object, Int flags);
};

class AIGuardMachine
{
public:
	char m_pad[0x10];
	Object *m_owner;
	char m_gap[0x30];
	Int m_targetToGuard;
	Int m_teamToGuard;
	PolygonTrigger *m_areaToGuard;
	char m_gap2[0x0c];
	Coord3D m_areaBox;
	unsigned char m_areaFlag;
	char m_gap4[0x03];
	Int m_nemesisID;
	Int m_containerFlag;
};

class AttackExitConditionsInterface
{
public:
	virtual bool shouldExit();
};

class ExitConditions : public AttackExitConditionsInterface
{
	public:
	Int m_conditionsToConsider;
	Coord3D m_center;
	Real m_radiusSqr;
	UnsignedInt m_attackGiveUpFrame;
};

class State
{
public:
	virtual void slot00();
	virtual void slot04();
	virtual void slot08();
	virtual void slot0c();
	virtual StateReturnType onEnter();
	virtual void onExit(Int status);
	virtual StateReturnType update();

	char m_pad[0x18];
	StateMachine *m_machine;
};

class NotifyWeaponFiredInterface
{
public:
	virtual void notifyFired() = 0;
};

class AIAttackState : public State, public NotifyWeaponFiredInterface
{
public:
	AIAttackState(StateMachine *machine, Bool follow, Bool attackingObject,
		Bool forceAttacking, AttackExitConditionsInterface *conditions);
	virtual StateReturnType onEnter();
	virtual void notifyFired();
};

class StateMachine
{
public:
	void setGoalObject(const Object *object);
};

class AIGuardOuterState : public State
{
public:
	virtual StateReturnType onEnter();

	char m_pad20[8];
	ExitConditions m_exitConditions;
	AIAttackState *m_attackState;
};

#define TheGameLogic (*(BfmeLook1011 **)0x012F0898)
#define TheTeamFactory (*(TeamFactory **)0x012ED810)
#define TheAI (*(AI **)0x012EF214)

extern Bool bfmeCallENJ(void *a, void *b);
extern Real getAdjustedVisionRangeForObject(const Object *object, Int flags);

StateReturnType AIGuardOuterState::onEnter()
{
	char *self = reinterpret_cast<char *>(this);
	char *container = *reinterpret_cast<char **>(self + 0x1c);

	Int containerFlag = *reinterpret_cast<Int *>(container + 0x70);
	if (containerFlag == 1)
		return STATE_SUCCESS;

	Coord3D position;

	{
	BfmeX1011 *target = TheGameLogic->bfmeFind1011(
		*reinterpret_cast<Int *>(container + 0x44));
	BfmeTeamXQ *teamRaw = TheTeamFactory->bfmeFindXQ(
		reinterpret_cast<void *>(*reinterpret_cast<Int *>(container + 0x48)));

	if (target)
	{
		position = target->m_coord;
	}
	else if (teamRaw)
	{
		teamRaw->bfmeEstimateXQ(&position);
	}
	else
	{
		char *container2 = *reinterpret_cast<char **>(self + 0x1c);
		position = *reinterpret_cast<Coord3D *>(container2 + 0x50);
	}
	}

	register BfmeX1011 *sub;
	container = *reinterpret_cast<char **>(self + 0x1c);
	AIGuardMachine *machine = reinterpret_cast<AIGuardMachine *>(container);
	Int nemesisID = *reinterpret_cast<Int *>(reinterpret_cast<char *>(machine) + 0x6c);
	sub = TheGameLogic->bfmeFind1011(
		nemesisID);
	if (!sub)
		return STATE_SUCCESS;

	Object *owner = machine->m_owner;
	if (owner->getLayer() != 1)
	{
		if (!bfmeCallENJ(owner, sub))
			return STATE_SUCCESS;
	}

	Real range = AI::getAdjustedVisionRangeForObject(owner, 3);

	char *container3 = reinterpret_cast<char *>(machine);
	PolygonTrigger *area = machine->m_areaToGuard;

	if (area)
	{
		if (*reinterpret_cast<unsigned char *>(container3 + 0x68))
			position = *reinterpret_cast<Coord3D *>(container3 + 0x5c);
		else
			area->getCenterPoint(&position);
	}

	*reinterpret_cast<Coord3D *>(self + 0x2c) = position;
	*reinterpret_cast<Real *>(self + 0x38) = range * position.x;

	*reinterpret_cast<Int *>(self + 0x3c) =
			TheGameLogic->m_frame + TheAI->m_aiData->m_guardChaseUnitFrames;
	*reinterpret_cast<Int *>(self + 0x28) = 7;

	AIAttackState *attack = new AIAttackState(
		reinterpret_cast<StateMachine *>(container), false, true, false,
		reinterpret_cast<AttackExitConditionsInterface *>(self + 0x24));
	*reinterpret_cast<AIAttackState **>(self + 0x40) = attack;

	StateMachine *attackMachine = *reinterpret_cast<StateMachine **>(
		reinterpret_cast<char *>(attack) + 0x1c);
	attackMachine->setGoalObject(reinterpret_cast<Object *>(sub));

	StateReturnType result = attack->onEnter();
	return result == STATE_CONTINUE ? STATE_CONTINUE : STATE_SUCCESS;
}
